import math
import torch
import torch.nn as nn
import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.extern .shared .align 4 .b8 smem[];
.visible .entry conv2d_forward(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 pN,
    .param .u32 pCin,
    .param .u32 pCout,
    .param .u32 pH,
    .param .u32 pW,
    .param .u32 pHout,
    .param .u32 pWout,
    .param .u32 pKh,
    .param .u32 pKw,
    .param .u32 pSh,
    .param .u32 pSw,
    .param .u32 pPh,
    .param .u32 pPw,
    .param .u32 pDh,
    .param .u32 pDw,
    .param .u32 pGroups,
    .param .u32 pCinPG,
    .param .u32 pCoutPG,
    .param .u32 pHasBias
)
{
    .reg .pred %p<40>;
    .reg .pred %pNA, %pOOB;
    .reg .b32 %r<220>;
    .reg .b64 %rd<120>;
    .reg .f32 %f<12>;
    // Explicitly declare named registers used below
    // 32-bit scalar params
    .reg .b32 %rN, %rCin, %rCout, %rH, %rW, %rHout, %rWout;
    .reg .b32 %rKh, %rKw, %rSh, %rSw, %rPh, %rPw, %rDh, %rDw;
    .reg .b32 %rGroups, %rCinPG, %rCoutPG, %rHasBias;
    // Thread/block indices
    .reg .b32 %rTx, %rTy, %rTz, %rBx, %rBy, %rBz, %rBDx, %rBDy, %rBDz;
    // Logical indices and temporaries
    .reg .b32 %rOw, %rOh, %rNOC, %rTot, %rNidx, %rOc, %rG, %rInBase;
    .reg .b32 %rInCh;
    // Signed/unsigned views and arithmetic temps
    .reg .b32 %rOh_s, %rOw_s, %rPh_s, %rPw_s, %rSh_s, %rSw_s, %rDh_s, %rDw_s, %rH_s, %rW_s;
    .reg .b32 %rIcg, %rKhIter, %rTmp1, %rTmp2, %rIh_s;
    .reg .b32 %rKwIter, %rTmp3, %rTmp4, %rIw_s;
    .reg .b32 %rTmp5, %rTmp6;
    .reg .b32 %rA, %rIh_u, %rIw_u, %rB, %rInIdx;
    .reg .b32 %rC, %rD, %rWIdx, %rY1, %rY2, %rYIdx;
    // Tiling registers
    .reg .b32 %rOhBase, %rOwBase, %rOhEnd, %rOwEnd, %rHoutm1, %rWoutm1, %rBDyMinus1, %rBDxMinus1, %rKhMinus1, %rKwMinus1;
    .reg .b32 %rOhBase_s, %rOwBase_s, %rOhEnd_s;
    .reg .b32 %rIhMin_s, %rIhMax_s, %rIwMin_s, %rIwMax_s, %rThAct, %rTwAct, %rTwm, %rTotal, %rGTid, %rCTA, %rIdx, %rTileH, %rTileW;
    .reg .b32 %rIhTileOff_s, %rIwTileOff_s, %rIhTileOff_u, %rIwTileOff_u, %rSmemElemOff;
    // Weight staging registers
    .reg .b32 %rTotalW, %rIdxW, %rKhW, %rKwW, %rInTileElems, %rWZBase, %rSmWIdx;
    // Additional channel-tile registers
    .reg .b32 %rICGTile, %rChIdx0, %rChIdx1, %rChIdx2, %rChIdx3, %rInCh0, %rInCh1, %rInCh2, %rInCh3;
    .reg .b32 %rBaseElemOff, %rSmemElemOffCT;
    .reg .b32 %rCTTmp;
    // 64-bit pointers/offsets
    .reg .b64 %rdInOff, %rdInPtr, %rdWOff, %rdWPtr, %rdBOff, %rdBPtr, %rdYOff, %rdYPtr;
    .reg .b64 %rdSmBase, %rdSmOff, %rdSmWBase, %rdSmWOff, %rdSmWPtr;
    .reg .b64 %rdSmLocPtr0, %rdSmLocPtr1, %rdSmLocPtr2, %rdSmLocPtr3;
    .reg .b64 %rdInTileStrideB, %rdWTileStrideB, %rdSmWZBasePtr;
    // Load pointers
    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [w_ptr];
    ld.param.u64 %rd3, [b_ptr];
    ld.param.u64 %rd4, [y_ptr];
    // Load scalars
    ld.param.u32 %rN, [pN];
    ld.param.u32 %rCin, [pCin];
    ld.param.u32 %rCout, [pCout];
    ld.param.u32 %rH, [pH];
    ld.param.u32 %rW, [pW];
    ld.param.u32 %rHout, [pHout];
    ld.param.u32 %rWout, [pWout];
    ld.param.u32 %rKh, [pKh];
    ld.param.u32 %rKw, [pKw];
    ld.param.u32 %rSh, [pSh];
    ld.param.u32 %rSw, [pSw];
    ld.param.u32 %rPh, [pPh];
    ld.param.u32 %rPw, [pPw];
    ld.param.u32 %rDh, [pDh];
    ld.param.u32 %rDw, [pDw];
    ld.param.u32 %rGroups, [pGroups];
    ld.param.u32 %rCinPG, [pCinPG];
    ld.param.u32 %rCoutPG, [pCoutPG];
    ld.param.u32 %rHasBias, [pHasBias];
    // Thread/block indices
    mov.u32 %rTx, %tid.x;
    mov.u32 %rTy, %tid.y;
    mov.u32 %rTz, %tid.z;
    mov.u32 %rBx, %ctaid.x;
    mov.u32 %rBy, %ctaid.y;
    mov.u32 %rBz, %ctaid.z;
    mov.u32 %rBDx, %ntid.x;
    mov.u32 %rBDy, %ntid.y;
    mov.u32 %rBDz, %ntid.z;
    // Compute logical indices
    mad.lo.u32 %rOw, %rBx, %rBDx, %rTx;
    mad.lo.u32 %rOh, %rBy, %rBDy, %rTy;
    mad.lo.u32 %rNOC, %rBz, %rBDz, %rTz;
    // total elements along N*Cout
    mul.lo.u32 %rTot, %rN, %rCout;
    // n and oc decomposition
    div.u32 %rNidx, %rNOC, %rCout;
    rem.u32 %rOc,   %rNOC, %rCout;
    // group and input-channel base within group
    div.u32 %rG, %rOc, %rCoutPG;       // g = oc / cout_pg
    mul.lo.u32 %rInBase, %rG, %rCinPG; // in_ch_base = g * cin_pg
    // Convert scalars to s32 where needed
    cvt.s32.u32 %rOh_s, %rOh;
    cvt.s32.u32 %rOw_s, %rOw;
    cvt.s32.u32 %rPh_s, %rPh;
    cvt.s32.u32 %rPw_s, %rPw;
    cvt.s32.u32 %rSh_s, %rSh;
    cvt.s32.u32 %rSw_s, %rSw;
    cvt.s32.u32 %rDh_s, %rDh;
    cvt.s32.u32 %rDw_s, %rDw;
    cvt.s32.u32 %rH_s, %rH;
    cvt.s32.u32 %rW_s, %rW;
    // Compute block tile bases and extents
    // oh_base = by*BDy; ow_base = bx*BDx
    mul.lo.u32 %rOhBase, %rBy, %rBDy;
    mul.lo.u32 %rOwBase, %rBx, %rBDx;
    // oh_end = min(oh_base + BDy - 1, Hout - 1);
    sub.u32 %rBDyMinus1, %rBDy, 1;
    add.u32 %rTmp1, %rOhBase, %rBDyMinus1;
    sub.u32 %rHoutm1, %rHout, 1;
    min.u32 %rOhEnd, %rTmp1, %rHoutm1;
    // ow_end = min(ow_base + BDx - 1, Wout - 1);
    sub.u32 %rBDxMinus1, %rBDx, 1;
    add.u32 %rTmp2, %rOwBase, %rBDxMinus1;
    sub.u32 %rWoutm1, %rWout, 1;
    min.u32 %rOwEnd, %rTmp2, %rWoutm1;
    // Convert bases/ends to s32
    cvt.s32.u32 %rOhBase_s, %rOhBase;
    cvt.s32.u32 %rOwBase_s, %rOwBase;
    cvt.s32.u32 %rOhEnd_s,  %rOhEnd;
    // ih_min = oh_base*Sh - Ph
    mul.lo.s32 %rTmp1, %rOhBase_s, %rSh_s;
    sub.s32    %rIhMin_s, %rTmp1, %rPh_s;
    // ih_max = oh_end*Sh - Ph + (Kh-1)*Dh
    mul.lo.s32 %rTmp2, %rOhEnd_s, %rSh_s;
    sub.s32    %rTmp2, %rTmp2, %rPh_s;
    sub.u32    %rKhMinus1, %rKh, 1;
    cvt.s32.u32 %rTmp3, %rKhMinus1;
    mul.lo.s32 %rTmp3, %rTmp3, %rDh_s;
    add.s32    %rIhMax_s, %rTmp2, %rTmp3;
    // iw_min = ow_base*Sw - Pw
    mul.lo.s32 %rTmp4, %rOwBase_s, %rSw_s;
    sub.s32    %rIwMin_s, %rTmp4, %rPw_s;
    // iw_max = ow_end*Sw - Pw + (Kw-1)*Dw
    cvt.s32.u32 %rTmp5, %rOwEnd;
    mul.lo.s32 %rTmp5, %rTmp5, %rSw_s;
    sub.s32    %rTmp5, %rTmp5, %rPw_s;
    sub.u32    %rKwMinus1, %rKw, 1;
    cvt.s32.u32 %rTmp6, %rKwMinus1;
    mul.lo.s32 %rTmp6, %rTmp6, %rDw_s;
    add.s32    %rIwMax_s, %rTmp5, %rTmp6;
    // Active tile sizes
    sub.s32 %rTmp1, %rIhMax_s, %rIhMin_s;
    add.s32 %rThAct, %rTmp1, 1;
    sub.s32 %rTmp2, %rIwMax_s, %rIwMin_s;
    add.s32 %rTwAct, %rTmp2, 1;
    // Twm = (BDx-1)*Sw + (Kw-1)*Dw + 1
    cvt.s32.u32 %rTmp3, %rBDxMinus1;
    mul.lo.s32 %rTmp3, %rTmp3, %rSw_s;
    cvt.s32.u32 %rTmp4, %rKwMinus1;
    mul.lo.s32 %rTmp4, %rTmp4, %rDw_s;
    add.s32    %rTmp3, %rTmp3, %rTmp4;
    add.s32    %rTmp3, %rTmp3, 1;
    cvt.u32.s32 %rTwm, %rTmp3;
    // Compute weight shared-memory base offset after input tile region
    cvt.u32.s32 %rInTileElems, %rThAct;
    mul.lo.u32 %rInTileElems, %rInTileElems, %rTwm;
    mov.f32 %f0, 0f00000000;
    mov.u64 %rdSmBase, smem;
    // CH_TILE = 4
    mov.u32 %rICGTile, 4;
    // smem layout: [CH_TILE * InTileElems] for inputs, then [BDz * CH_TILE * TotalW] for weights
    mul.lo.u32 %rCTTmp, %rInTileElems, %rICGTile;
    mul.wide.u32 %rdSmWOff, %rCTTmp, 4;
    add.u64 %rdSmWBase, %rdSmBase, %rdSmWOff;
    // CTA and thread linear indices for cooperative load
    mul.lo.u32 %rCTA, %rBDx, %rBDy;
    mad.lo.u32 %rGTid, %rTy, %rBDx, %rTx;
    // Precompute not-active predicate: pNA = (ow>=Wout) || (oh>=Hout) || (NOC>=Tot)
    setp.ge.u32 %p0, %rOw, %rWout;
    setp.ge.u32 %p1, %rOh, %rHout;
    setp.ge.u32 %p2, %rNOC, %rTot;
    or.pred %p3, %p0, %p1;
    or.pred %pNA, %p3, %p2;
    // Precompute strides in bytes
    mul.wide.u32 %rdInTileStrideB, %rInTileElems, 4;
    // icg loop in tiles of 4
    mov.u32 %rIcg, 0;
ICG_LOOP:
    setp.ge.u32 %p4, %rIcg, %rCinPG;
    @%p4 bra ICG_END;
    // Prepare channel indices and validity for up to 4 channels
    add.u32 %rChIdx0, %rIcg, 0;
    add.u32 %rChIdx1, %rIcg, 1;
    add.u32 %rChIdx2, %rIcg, 2;
    add.u32 %rChIdx3, %rIcg, 3;
    setp.lt.u32 %p20, %rChIdx0, %rCinPG;
    setp.lt.u32 %p21, %rChIdx1, %rCinPG;
    setp.lt.u32 %p22, %rChIdx2, %rCinPG;
    setp.lt.u32 %p23, %rChIdx3, %rCinPG;
    // Compute absolute input channels
    mad.lo.u32 %rInCh0, %rG, 0, %rInBase; // base only
    add.u32 %rInCh0, %rInBase, %rChIdx0;
    add.u32 %rInCh1, %rInBase, %rChIdx1;
    add.u32 %rInCh2, %rInBase, %rChIdx2;
    add.u32 %rInCh3, %rInBase, %rChIdx3;
    // Cooperative load input tiles for up to 4 channels into shared memory
    // total elements = ThAct * TwAct
    cvt.u32.s32 %rTmp1, %rThAct;
    cvt.u32.s32 %rTmp2, %rTwAct;
    mul.lo.u32 %rTotal, %rTmp1, %rTmp2;
    mov.u32 %rIdx, %rGTid;
SMEM_LOAD_LOOP_TILED:
    setp.ge.u32 %p5, %rIdx, %rTotal;
    @%p5 bra SMEM_LOAD_DONE_TILED;
    // th = idx / TwAct; tw = idx % TwAct
    div.u32 %rTileH, %rIdx, %rTmp2;
    rem.u32 %rTileW, %rIdx, %rTmp2;
    // ih = ih_min + th; iw = iw_min + tw
    cvt.s32.u32 %rTmp3, %rTileH;
    add.s32 %rTmp3, %rIhMin_s, %rTmp3;
    cvt.s32.u32 %rTmp4, %rTileW;
    add.s32 %rTmp4, %rIwMin_s, %rTmp4;
    // bounds check input (spatial)
    setp.lt.s32 %p6, %rTmp3, 0;
    setp.ge.s32 %p7, %rTmp3, %rH_s;
    or.pred %p8, %p6, %p7;
    setp.lt.s32 %p9, %rTmp4, 0;
    setp.ge.s32 %p10, %rTmp4, %rW_s;
    or.pred %p11, %p9, %p10;
    or.pred %pOOB, %p8, %p11;
    // common smem base element offset for this (th,tw)
    mul.lo.u32 %rBaseElemOff, %rTileH, %rTwm;
    add.u32 %rBaseElemOff, %rBaseElemOff, %rTileW;
    // Channel 0
    // smem dst for ch0
    mov.u32 %rCTTmp, 0;
    mul.lo.u32 %rSmemElemOffCT, %rInTileElems, %rCTTmp;
    add.u32 %rSmemElemOffCT, %rSmemElemOffCT, %rBaseElemOff;
    mul.wide.u32 %rdSmOff, %rSmemElemOffCT, 4;
    add.u64 %rdSmOff, %rdSmBase, %rdSmOff;
    not.pred %p24, %pOOB;
    and.pred %p25, %p20, %p24;
    @%p25 bra LDO_CH0;
    mov.f32 %f1, 0f00000000;
    st.shared.f32 [%rdSmOff], %f1;
    bra LEND_CH0;
LDO_CH0:
    cvt.u32.s32 %rIh_u, %rTmp3;
    cvt.u32.s32 %rIw_u, %rTmp4;
    mad.lo.u32 %rA, %rNidx, %rCin, %rInCh0;
    mad.lo.u32 %rB, %rA, %rH, %rIh_u;
    mad.lo.u32 %rInIdx, %rB, %rW, %rIw_u;
    mul.wide.u32 %rdInOff, %rInIdx, 4;
    add.u64 %rdInPtr, %rd1, %rdInOff;
    cp.async.ca.shared.global [%rdSmOff], [%rdInPtr], 4;
LEND_CH0:
    // Channel 1
    mov.u32 %rCTTmp, 1;
    mul.lo.u32 %rSmemElemOffCT, %rInTileElems, %rCTTmp;
    add.u32 %rSmemElemOffCT, %rSmemElemOffCT, %rBaseElemOff;
    mul.wide.u32 %rdSmOff, %rSmemElemOffCT, 4;
    add.u64 %rdSmOff, %rdSmBase, %rdSmOff;
    not.pred %p26, %pOOB;
    and.pred %p27, %p21, %p26;
    @%p27 bra LDO_CH1;
    mov.f32 %f1, 0f00000000;
    st.shared.f32 [%rdSmOff], %f1;
    bra LEND_CH1;
LDO_CH1:
    cvt.u32.s32 %rIh_u, %rTmp3;
    cvt.u32.s32 %rIw_u, %rTmp4;
    mad.lo.u32 %rA, %rNidx, %rCin, %rInCh1;
    mad.lo.u32 %rB, %rA, %rH, %rIh_u;
    mad.lo.u32 %rInIdx, %rB, %rW, %rIw_u;
    mul.wide.u32 %rdInOff, %rInIdx, 4;
    add.u64 %rdInPtr, %rd1, %rdInOff;
    cp.async.ca.shared.global [%rdSmOff], [%rdInPtr], 4;
LEND_CH1:
    // Channel 2
    mov.u32 %rCTTmp, 2;
    mul.lo.u32 %rSmemElemOffCT, %rInTileElems, %rCTTmp;
    add.u32 %rSmemElemOffCT, %rSmemElemOffCT, %rBaseElemOff;
    mul.wide.u32 %rdSmOff, %rSmemElemOffCT, 4;
    add.u64 %rdSmOff, %rdSmBase, %rdSmOff;
    not.pred %p28, %pOOB;
    and.pred %p29, %p22, %p28;
    @%p29 bra LDO_CH2;
    mov.f32 %f1, 0f00000000;
    st.shared.f32 [%rdSmOff], %f1;
    bra LEND_CH2;
LDO_CH2:
    cvt.u32.s32 %rIh_u, %rTmp3;
    cvt.u32.s32 %rIw_u, %rTmp4;
    mad.lo.u32 %rA, %rNidx, %rCin, %rInCh2;
    mad.lo.u32 %rB, %rA, %rH, %rIh_u;
    mad.lo.u32 %rInIdx, %rB, %rW, %rIw_u;
    mul.wide.u32 %rdInOff, %rInIdx, 4;
    add.u64 %rdInPtr, %rd1, %rdInOff;
    cp.async.ca.shared.global [%rdSmOff], [%rdInPtr], 4;
LEND_CH2:
    // Channel 3
    mov.u32 %rCTTmp, 3;
    mul.lo.u32 %rSmemElemOffCT, %rInTileElems, %rCTTmp;
    add.u32 %rSmemElemOffCT, %rSmemElemOffCT, %rBaseElemOff;
    mul.wide.u32 %rdSmOff, %rSmemElemOffCT, 4;
    add.u64 %rdSmOff, %rdSmBase, %rdSmOff;
    not.pred %p30, %pOOB;
    and.pred %p31, %p23, %p30;
    @%p31 bra LDO_CH3;
    mov.f32 %f1, 0f00000000;
    st.shared.f32 [%rdSmOff], %f1;
    bra LEND_CH3;
LDO_CH3:
    cvt.u32.s32 %rIh_u, %rTmp3;
    cvt.u32.s32 %rIw_u, %rTmp4;
    mad.lo.u32 %rA, %rNidx, %rCin, %rInCh3;
    mad.lo.u32 %rB, %rA, %rH, %rIh_u;
    mad.lo.u32 %rInIdx, %rB, %rW, %rIw_u;
    mul.wide.u32 %rdInOff, %rInIdx, 4;
    add.u64 %rdInPtr, %rd1, %rdInOff;
    cp.async.ca.shared.global [%rdSmOff], [%rdInPtr], 4;
LEND_CH3:
    // next spatial idx
    add.u32 %rIdx, %rIdx, %rCTA;
    bra SMEM_LOAD_LOOP_TILED;
SMEM_LOAD_DONE_TILED:
    // finalize async copies
    cp.async.commit_group;
    cp.async.wait_group 0;
    // Cooperative load weights for up to 4 channels for this oc into shared memory region after input tiles
    mul.lo.u32 %rTotalW, %rKh, %rKw;
    // per-OC shared-memory base offset (in elements) for weights with CH_TILE: tz * (CH_TILE*Kh*Kw)
    mul.lo.u32 %rCTTmp, %rICGTile, %rTotalW;
    mul.lo.u32 %rWZBase, %rTz, %rCTTmp;
    // Compute weight tile stride in bytes (per channel)
    mul.wide.u32 %rdWTileStrideB, %rTotalW, 4;
    // Base pointer for (tz) section
    mul.wide.u32 %rdSmWOff, %rWZBase, 4;
    add.u64 %rdSmWZBasePtr, %rdSmWBase, %rdSmWOff;
    mov.u32 %rIdxW, %rGTid;
W_SMEM_LOAD_LOOP_TILED:
    setp.ge.u32 %p19, %rIdxW, %rTotalW;
    @%p19 bra W_SMEM_LOAD_DONE_TILED;
    // kh = idxW / Kw; kw = idxW % Kw
    div.u32 %rKhW, %rIdxW, %rKw;
    rem.u32 %rKwW, %rIdxW, %rKw;
    // Channel 0
    @!%p20 bra W_SKIP_CH0;
    mad.lo.u32 %rC, %rOc, %rCinPG, %rChIdx0;
    mad.lo.u32 %rD, %rC, %rKh, %rKhW;
    mad.lo.u32 %rWIdx, %rD, %rKw, %rKwW;
    mul.wide.u32 %rdWOff, %rWIdx, 4;
    add.u64 %rdWPtr, %rd2, %rdWOff;
    // smem idx: cti*TotalW + idxW
    // ptr: rdSmWZBasePtr + 0*rdWTileStrideB + idxW*4
    mul.wide.u32 %rdSmWOff, %rIdxW, 4;
    add.u64 %rdSmWPtr, %rdSmWZBasePtr, %rdSmWOff;
    cp.async.ca.shared.global [%rdSmWPtr], [%rdWPtr], 4;
W_SKIP_CH0:
    // Channel 1
    @!%p21 bra W_SKIP_CH1;
    mad.lo.u32 %rC, %rOc, %rCinPG, %rChIdx1;
    mad.lo.u32 %rD, %rC, %rKh, %rKhW;
    mad.lo.u32 %rWIdx, %rD, %rKw, %rKwW;
    mul.wide.u32 %rdWOff, %rWIdx, 4;
    add.u64 %rdWPtr, %rd2, %rdWOff;
    // ptr: rdSmWZBasePtr + 1*rdWTileStrideB + idxW*4
    mul.wide.u32 %rdSmWOff, %rIdxW, 4;
    add.u64 %rdSmWOff, %rdSmWOff, %rdWTileStrideB;
    add.u64 %rdSmWPtr, %rdSmWZBasePtr, %rdSmWOff;
    cp.async.ca.shared.global [%rdSmWPtr], [%rdWPtr], 4;
W_SKIP_CH1:
    // Channel 2
    @!%p22 bra W_SKIP_CH2;
    mad.lo.u32 %rC, %rOc, %rCinPG, %rChIdx2;
    mad.lo.u32 %rD, %rC, %rKh, %rKhW;
    mad.lo.u32 %rWIdx, %rD, %rKw, %rKwW;
