def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_forward")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        if isinstance(kernel_size, tuple):
            assert kernel_size[0] == kernel_size[1], "Only square kernels supported"
            k = int(kernel_size[0])
        else:
            k = int(kernel_size)
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = k
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)
        assert self.in_channels % self.groups == 0, "in_channels must be divisible by groups"
        assert self.out_channels % self.groups == 0, "out_channels must be divisible by groups"

        # Parameters shape match torch.nn.Conv2d
        weight = torch.empty(self.out_channels, self.in_channels // self.groups, k, k)
        init.kaiming_uniform_(weight, a=math.sqrt(5))
        self.weight = nn.Parameter(weight)

        if bias:
            fan_in = (self.in_channels // self.groups) * k * k
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            b = torch.empty(self.out_channels)
            init.uniform_(b, -bound, bound)
            self.bias = nn.Parameter(b)
        else:
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 tensors are supported"
        N, Cin, H, W = x.shape
        assert Cin == self.in_channels, "Input channels mismatch"
        k = self.kernel_size
        sh = self.stride
        sw = self.stride
        ph = self.padding
        pw = self.padding
        dh = self.dilation
        dw = self.dilation
        groups = self.groups

        # Output dimensions
        Hout = (H + 2 * ph - dh * (k - 1) - 1) // sh + 1
        Wout = (W + 2 * pw - dw * (k - 1) - 1) // sw + 1

        y = torch.empty((N, self.out_channels, Hout, Wout), device=x.device, dtype=x.dtype)

        cin_pg = self.in_channels // groups
        cout_pg = self.out_channels // groups
        has_bias = 1 if self.bias is not None else 0

        module = _get_ptx_module()

        # Launch configuration: each thread computes one (n, oc, oh, ow)
        block_x = 32
        block_y = 4
        # Tile multiple output channels per CTA along z to reuse input tiles
        if self.out_channels % 4 == 0:
            block_z = 4
            grid_z = N * (self.out_channels // block_z)
        else:
            block_z = 1
            grid_z = N * self.out_channels
        grid_x = (Wout + block_x - 1) // block_x
        grid_y = (Hout + block_y - 1) // block_y
        th_max = (block_y - 1) * sh + (k - 1) * dh + 1
        tw_max = (block_x - 1) * sw + (k - 1) * dw + 1
        shared_mem_bytes = (th_max * tw_max + block_z * k * k) * 4
        module.launch(
            "conv2d_forward",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, block_z),
            arguments=[
                x,                       # x_ptr
                self.weight,             # w_ptr
                (self.bias if self.bias is not None else u64(0)),  # b_ptr (0 if no bias)
                y,                       # y_ptr
                i32(N),
                i32(self.in_channels),
                i32(self.out_channels),
                i32(H),
                i32(W),
                i32(Hout),
                i32(Wout),
                i32(k),
                i32(k),
                i32(sh),
                i32(sw),
                i32(ph),
                i32(pw),
                i32(dh),
                i32(dw),
                i32(groups),
                i32(cin_pg),
                i32(cout_pg),
                i32(has_bias),
            ],
            shared_memory=int(shared_mem_bytes),
            stream=torch.cuda.current_stream(x.device),
        )
        return y

