    cvt.s32.u32 %rTmp5, %rOwEnd;
    mul.lo.s32 %rTmp5, %rTmp5, %rSw_s;
    sub.s32    %rTmp5, %rTmp5, %rPw_s;
    sub.u32    %rKwMinus1, %rKw, 1;
