    // next spatial idx
    add.u32 %rIdx, %rIdx, %rCTA;
    bra SMEM_LOAD_LOOP_TILED;
SMEM_LOAD_DONE_TILED:
    // finalize async copies
    cp.async.commit_group;
    cp.async.wait_group 0;
    // Cooperative load weights for up to 4 channels for this oc into shared memory region after input tiles
    mul.lo.u32 %rTotalW, %rKh, %rKw;
    // per-OC shared-memory base offset (in elements) for weights with CH_TILE: tz * (CH_TILE*Kh*Kw)
    mul.lo.u32 %rCTTmp, %rICGTile, %rTotalW;
    mul.lo.u32 %rWZBase, %rTz, %rCTTmp;
    // Compute weight tile stride in bytes (per channel)
    mul.wide.u32 %rdWTileStrideB, %rTotalW, 4;
    // Base pointer for (tz) section
    mul.wide.u32 %rdSmWOff, %rWZBase, 4;
    add.u64 %rdSmWZBasePtr, %rdSmWBase, %rdSmWOff;
    mov.u32 %rIdxW, %rGTid;
W_SMEM_LOAD_LOOP_TILED:
    setp.ge.u32 %p19, %rIdxW, %rTotalW;
    @%p19 bra W_SMEM_LOAD_DONE_TILED;
    // kh = idxW / Kw; kw = idxW % Kw
    div.u32 %rKhW, %rIdxW, %rKw;
    rem.u32 %rKwW, %rIdxW, %rKw;
    // Channel 0
    @!%p20 bra W_SKIP_CH0;
    mad.lo.u32 %rC, %rOc, %rCinPG, %rChIdx0;
    mad.lo.u32 %rD, %rC, %rKh, %rKhW;
    mad.lo.u32 %rWIdx, %rD, %rKw, %rKwW;
    mul.wide.u32 %rdWOff, %rWIdx, 4;
    add.u64 %rdWPtr, %rd2, %rdWOff;
    // smem idx: cti*TotalW + idxW
    // ptr: rdSmWZBasePtr + 0*rdWTileStrideB + idxW*4
    mul.wide.u32 %rdSmWOff, %rIdxW, 4;
    add.u64 %rdSmWPtr, %rdSmWZBasePtr, %rdSmWOff;
    cp.async.ca.shared.global [%rdSmWPtr], [%rdWPtr], 4;
W_SKIP_CH0:
    // Channel 1
    @!%p21 bra W_SKIP_CH1;
    mad.lo.u32 %rC, %rOc, %rCinPG, %rChIdx1;
    mad.lo.u32 %rD, %rC, %rKh, %rKhW;
    mad.lo.u32 %rWIdx, %rD, %rKw, %rKwW;
    mul.wide.u32 %rdWOff, %rWIdx, 4;
    add.u64 %rdWPtr, %rd2, %rdWOff;
    // ptr: rdSmWZBasePtr + 1*rdWTileStrideB + idxW*4
    mul.wide.u32 %rdSmWOff, %rIdxW, 4;
    add.u64 %rdSmWOff, %rdSmWOff, %rdWTileStrideB;
    add.u64 %rdSmWPtr, %rdSmWZBasePtr, %rdSmWOff;
    cp.async.ca.shared.global [%rdSmWPtr], [%rdWPtr], 4;
W_SKIP_CH1:
    // Channel 2
    @!%p22 bra W_SKIP_CH2;
    mad.lo.u32 %rC, %rOc, %rCinPG, %rChIdx2;
    mad.lo.u32 %rD, %rC, %rKh, %rKhW;
    mad.lo.u32 %rWIdx, %rD, %rKw, %rKwW;
    mul.wide.u32 %rdWOff, %rWIdx, 4;
    add.u64 %rdWPtr, %rd2, %rdWOff;
    // ptr: rdSmWZBasePtr + 2*rdWTileStrideB + idxW*4
    mul.wide.u32 %rdSmWOff, %rIdxW, 4;
    add.u64 %rdSmWOff, %rdSmWOff, %rdWTileStrideB;
    add.u64 %rdSmWOff, %rdSmWOff, %rdWTileStrideB;
    add.u64 %rdSmWPtr, %rdSmWZBasePtr, %rdSmWOff;
    cp.async.ca.shared.global [%rdSmWPtr], [%rdWPtr], 4;
W_SKIP_CH2:
    // Channel 3
    @!%p23 bra W_SKIP_CH3;
    mad.lo.u32 %rC, %rOc, %rCinPG, %rChIdx3;
    mad.lo.u32 %rD, %rC, %rKh, %rKhW;
    mad.lo.u32 %rWIdx, %rD, %rKw, %rKwW;
    mul.wide.u32 %rdWOff, %rWIdx, 4;
    add.u64 %rdWPtr, %rd2, %rdWOff;
    // ptr: rdSmWZBasePtr + 3*rdWTileStrideB + idxW*4
    mul.wide.u32 %rdSmWOff, %rIdxW, 4;
    add.u64 %rdSmWOff, %rdSmWOff, %rdWTileStrideB;
    add.u64 %rdSmWOff, %rdSmWOff, %rdWTileStrideB;
    add.u64 %rdSmWOff, %rdSmWOff, %rdWTileStrideB;
    add.u64 %rdSmWPtr, %rdSmWZBasePtr, %rdSmWOff;
    cp.async.ca.shared.global [%rdSmWPtr], [%rdWPtr], 4;
W_SKIP_CH3:
    // next weight idx
    add.u32 %rIdxW, %rIdxW, %rCTA;
    bra W_SMEM_LOAD_LOOP_TILED;
W_SMEM_LOAD_DONE_TILED:
    // synchronize before compute
    cp.async.commit_group;
    cp.async.wait_group 0;
    bar.sync 0;
    // If thread not active, skip compute but continue to next icg-tile
    @%pNA bra ICG_CONTINUE;
    // kh loop
    mov.u32 %rKhIter, 0;
KH_LOOP:
    setp.ge.u32 %p12, %rKhIter, %rKh;
    @%p12 bra KH_END;
    // ih = oh*Sh - Ph + kh*Dh
    mul.lo.s32 %rTmp1, %rOh_s, %rSh_s;
    mul.lo.s32 %rTmp2, %rKhIter, %rDh_s;
    add.s32    %rIh_s, %rTmp1, %rTmp2;
    sub.s32    %rIh_s, %rIh_s, %rPh_s;
    // if ih out of bounds, skip kw loop
    setp.lt.s32 %p13, %rIh_s, 0;
    @%p13 bra KH_CONT;
    setp.ge.s32 %p14, %rIh_s, %rH_s;
    @%p14 bra KH_CONT;
    // kw loop
    mov.u32 %rKwIter, 0;
KW_LOOP:
    setp.ge.u32 %p15, %rKwIter, %rKw;
    @%p15 bra KW_END;
    // iw = ow*Sw - Pw + kw*Dw
    mul.lo.s32 %rTmp3, %rOw_s, %rSw_s;
    mul.lo.s32 %rTmp4, %rKwIter, %rDw_s;
    add.s32    %rIw_s, %rTmp3, %rTmp4;
    sub.s32    %rIw_s, %rIw_s, %rPw_s;
    // if iw out of bounds, continue
    setp.lt.s32 %p16, %rIw_s, 0;
    @%p16 bra KW_CONT;
    setp.ge.s32 %p17, %rIw_s, %rW_s;
    @%p17 bra KW_CONT;
    // Load from shared memory: offsets based on tile origin (ih_min, iw_min)
    sub.s32 %rIhTileOff_s, %rIh_s, %rIhMin_s;
    sub.s32 %rIwTileOff_s, %rIw_s, %rIwMin_s;
    cvt.u32.s32 %rIhTileOff_u, %rIhTileOff_s;
    cvt.u32.s32 %rIwTileOff_u, %rIwTileOff_s;
    mul.lo.u32 %rSmemElemOff, %rIhTileOff_u, %rTwm;
    add.u32 %rSmemElemOff, %rSmemElemOff, %rIwTileOff_u;
    mul.wide.u32 %rdSmOff, %rSmemElemOff, 4;
    add.u64 %rdSmLocPtr0, %rdSmBase, %rdSmOff;
    add.u64 %rdSmLocPtr1, %rdSmLocPtr0, %rdInTileStrideB;
    add.u64 %rdSmLocPtr2, %rdSmLocPtr1, %rdInTileStrideB;
    add.u64 %rdSmLocPtr3, %rdSmLocPtr2, %rdInTileStrideB;
    // Load weights from shared memory: base idxW = kh*Kw + kw for tz-section, add cti*TotalW
    mad.lo.u32 %rWIdx, %rKhIter, %rKw, %rKwIter;
    // Base ptr for tz section computed earlier: rdSmWZBasePtr
    mul.wide.u32 %rdSmWOff, %rWIdx, 4;
    add.u64 %rdSmWPtr, %rdSmWZBasePtr, %rdSmWOff;
    // Channel 0 accumulate
    @!%p20 bra SKIP_ACC_CH0;
    ld.shared.f32 %f1, [%rdSmLocPtr0];
    ld.shared.f32 %f2, [%rdSmWPtr];
    fma.rn.f32 %f0, %f1, %f2, %f0;
SKIP_ACC_CH0:
    // Channel 1 accumulate
    @!%p21 bra SKIP_ACC_CH1;
    ld.shared.f32 %f1, [%rdSmLocPtr1];
    add.u64 %rdSmWOff, %rdSmWPtr, %rdWTileStrideB;
    ld.shared.f32 %f2, [%rdSmWOff];
    fma.rn.f32 %f0, %f1, %f2, %f0;
SKIP_ACC_CH1:
    // Channel 2 accumulate
    @!%p22 bra SKIP_ACC_CH2;
    ld.shared.f32 %f1, [%rdSmLocPtr2];
    add.u64 %rdSmWOff, %rdSmWPtr, %rdWTileStrideB;
    add.u64 %rdSmWOff, %rdSmWOff, %rdWTileStrideB;
    ld.shared.f32 %f2, [%rdSmWOff];
    fma.rn.f32 %f0, %f1, %f2, %f0;
SKIP_ACC_CH2:
    // Channel 3 accumulate
    @!%p23 bra SKIP_ACC_CH3;
    ld.shared.f32 %f1, [%rdSmLocPtr3];
    add.u64 %rdSmWOff, %rdSmWPtr, %rdWTileStrideB;
    add.u64 %rdSmWOff, %rdSmWOff, %rdWTileStrideB;
    add.u64 %rdSmWOff, %rdSmWOff, %rdWTileStrideB;
    ld.shared.f32 %f2, [%rdSmWOff];
    fma.rn.f32 %f0, %f1, %f2, %f0;
SKIP_ACC_CH3:
KW_CONT:
    add.u32 %rKwIter, %rKwIter, 1;
    bra KW_LOOP;
KW_END:
KH_CONT:
    add.u32 %rKhIter, %rKhIter, 1;
    bra KH_LOOP;
KH_END:
ICG_CONTINUE:
    bar.sync 0;
    add.u32 %rIcg, %rIcg, 4;
    bra ICG_LOOP;
ICG_END:
    // If thread not active, skip bias and store
    @%pNA bra EXIT;
    // Add bias if present
    setp.eq.u32 %p18, %rHasBias, 0;
    @%p18 bra NO_BIAS;
    mul.wide.u32 %rdBOff, %rOc, 4;
    add.u64 %rdBPtr, %rd3, %rdBOff;
    ld.global.f32 %f3, [%rdBPtr];
    add.f32 %f0, %f0, %f3;
NO_BIAS:
    // Store output: (((n*Cout + oc)*Hout + oh)*Wout + ow)
    mad.lo.u32 %rY1, %rNidx, %rCout, %rOc;
    mad.lo.u32 %rY2, %rY1, %rHout, %rOh;
    mad.lo.u32 %rYIdx, %rY2, %rWout, %rOw;
    mul.wide.u32 %rdYOff, %rYIdx, 4;
    add.u64 %rdYPtr, %rd4, %rdYOff;
    st.global.f32 [%rdYPtr], %f0;
EXIT:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_forward")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        if isinstance(kernel_size, tuple):
            assert kernel_size[0] == kernel_size[1], "Only square kernels supported"
            k = int(kernel_size[0])
        else:
            k = int(kernel_size)
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = k
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)
        assert self.in_channels % self.groups == 0, "in_channels must be divisible by groups"
        assert self.out_channels % self.groups == 0, "out_channels must be divisible by groups"

        # Parameters shape match torch.nn.Conv2d
        weight = torch.empty(self.out_channels, self.in_channels // self.groups, k, k)
        init.kaiming_uniform_(weight, a=math.sqrt(5))
        self.weight = nn.Parameter(weight)

        if bias:
            fan_in = (self.in_channels // self.groups) * k * k
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            b = torch.empty(self.out_channels)
            init.uniform_(b, -bound, bound)
            self.bias = nn.Parameter(b)
        else:
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 tensors are supported"
        N, Cin, H, W = x.shape
        assert Cin == self.in_channels, "Input channels mismatch"
        k = self.kernel_size
        sh = self.stride
        sw = self.stride
        ph = self.padding
        pw = self.padding
        dh = self.dilation
        dw = self.dilation
        groups = self.groups

        # Output dimensions
        Hout = (H + 2 * ph - dh * (k - 1) - 1) // sh + 1
        Wout = (W + 2 * pw - dw * (k - 1) - 1) // sw + 1

        y = torch.empty((N, self.out_channels, Hout, Wout), device=x.device, dtype=x.dtype)

        cin_pg = self.in_channels // groups
        cout_pg = self.out_channels // groups
        has_bias = 1 if self.bias is not None else 0

        module = _get_ptx_module()

        # Launch configuration: each thread computes one (n, oc, oh, ow)
        block_x = 32
        block_y = 4
        # Tile multiple output channels per CTA along z to reuse input tiles
        if self.out_channels % 4 == 0:
            block_z = 4
            grid_z = N * (self.out_channels // block_z)
        else:
            block_z = 1
            grid_z = N * self.out_channels
        grid_x = (Wout + block_x - 1) // block_x
        grid_y = (Hout + block_y - 1) // block_y
        th_max = (block_y - 1) * sh + (k - 1) * dh + 1
        tw_max = (block_x - 1) * sw + (k - 1) * dw + 1
        shared_mem_bytes = (4 * th_max * tw_max + block_z * 4 * k * k) * 4
        module.launch(
            "conv2d_forward",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, block_z),
            arguments=[
                x,                       # x_ptr
                self.weight,             # w_ptr
                (self.bias if self.bias is not None else u64(0)),  # b_ptr (0 if no bias)
                y,                       # y_ptr
                i32(N),
                i32(self.in_channels),
                i32(self.out_channels),
                i32(H),
                i32(W),
                i32(Hout),
                i32(Wout),
                i32(k),
                i32(k),
                i32(sh),
                i32(sw),
                i32(ph),
                i32(pw),
                i32(dh),
                i32(dw),
                i32(groups),
                i32(cin_pg),
                i32(cout_pg),
                i32(has_bias),
            ],
            shared_memory=int(shared_mem_bytes),
            stream=torch.cuda.current_stream(x.device),
        )
        return y
